struct qstr { unsigned int len; const unsigned char *name; };
struct dentry { struct qstr d_name; };
typedef struct { int dummy; } handle_t;

extern void ext4_warning(struct super_block *sb, const char *fmt, ...);
extern void drop_nlink(struct inode *inode);
extern void ext4_orphan_add(handle_t *handle, struct inode *inode);

static void check(struct inode *inode, handle_t *handle)
{
	if (!inode->i_nlink) {
		ext4_warning(inode->i_sb,
			     "Deleting nonexistent file (%lu), %d",
			     inode->i_ino, inode->i_nlink);
	} else
		drop_nlink(inode);
	if (!inode->i_nlink)
		ext4_orphan_add(handle, inode);
}

